import{_ as i,o as a,c as n,ai as l}from"./chunks/framework.Ai2o9gNv.js";const g=JSON.parse('{"title":"49-拓展（1）","description":"","frontmatter":{},"headers":[],"relativePath":"仓颉入门到实战/49-拓展（1）/49-拓展（1）.md","filePath":"仓颉入门到实战/49-拓展（1）/49-拓展（1）.md","lastUpdated":1739110422000,"__rawMarkdown":"# 49-拓展（1）\\n\\n## 扩展概述\\n\\n扩展可以为在当前 `package` 可见的类型（除函数、元组、接口）添加新功能。\\n\\n当不能破坏被扩展类型的封装性，但希望添加额外的功能时，可以使用扩展。\\n\\n可以添加的功能包括：\\n\\n- **添加成员函数**\\n- **添加操作符重载函数**\\n- **添加成员属性**\\n- **实现接口**\\n\\n扩展虽然可以添加额外的功能，但不能变更被扩展类型的封装性，因此扩展不支持以下功能：\\n\\n1. 扩展不能增加成员变量。\\n2. 扩展的函数和属性必须拥有实现。\\n3. 扩展的函数和属性不能使用 `open`、`override`、 `redef`修饰。\\n4. 扩展不能访问被扩展类型中 `private` 修饰的成员。\\n\\n根据扩展有没有实现新的接口，扩展可以分为 **直接扩展** 和 **接口扩展** 两种用法，直接扩展即不包含额外接口的扩展；接口扩展即包含接口的扩展，接口扩展可以用来为现有的类型添加新功能并实现接口，增强抽象灵活性。\\n\\n## 直接拓展\\n\\n对类型直接进行拓展称为直接拓展。\\n\\n## 简单拓展\\n\\n这里演示一个比较简单的拓展类型的用法。 给String类型拓展一个printSize的方法。\\n\\n需要注意的是，String类型本身具有size属性，所以 `this.size`不会出错\\n\\n```typescript\\nextend String {\\n    public func printSize() {\\n        println(\\"the size is ${this.size}\\")\\n    }\\n}\\n\\nmain() {\\n    let a = \\"123\\"\\n    a.printSize() // the size is 3\\n}\\n```\\n\\n## 泛型拓展\\n\\n当被拓展的类型是泛型时，提供了两种方式对泛型类型进行拓展。\\n\\n1. 针对特定泛型实例化类型进行扩展\\n2. `extend` 后面引入泛型形参的泛型扩展\\n\\n两种区别主要在写法不同上\\n\\n### 针对特定泛型实例化类型进行扩展\\n\\n针对特定泛型实例化类型进行扩展，关键字 `extend` 后允许带一个任意实例化完全的泛型类型。为这些类型增加的功能只有在类型完全匹配时才能使用，且泛型类型的类型实参必须符合泛型类型定义处的约束要求。\\n\\n如下列代码， A是B的父类。B必定包含A所有的实现，所以where的约束生效。\\n\\n```typescript\\nopen class A {\\n    func a() {\\n        return true\\n    }\\n}\\n\\nclass B <: A {\\n    func b() {\\n        return true\\n    }\\n}\\n\\nclass Foo<T> where T <: A {}\\n\\nextend Foo<B> {} \\n\\nmain() {\\n    var a = Foo<B>()\\n}\\n```\\n\\n### extend 后面引入泛型形参的泛型扩展\\n\\n在 `extend` 后面引入泛型形参的泛型扩展。泛型扩展可以用来扩展未实例化或未完全实例化的泛型类型。在 `extend` 后声明的泛\\n\\n型形参必须被直接或间接使用在被扩展的泛型类型上。为这些类型增加的功能只有在类型和约束完全匹配时才能使用。\\n\\n```typescript\\nclass MyList<T> {\\n    public let data: Array<T> = Array<T>()\\n}\\n\\nextend<T> MyList<T> {} // OK\\nextend<R> MyList<R> {} // OK\\nextend<T, R> MyList<(T, R)> {} // OK\\n```\\n\\n例如可以定义一个叫 Pair 的类型，这个类型可以方便地存储两个元素（类似于 Tuple）。\\n\\n希望 Pair 类型可以容纳任何类型，因此两个泛型变元不应该有任何约束，这样才能保证 Pair 能容纳所有类型。\\n\\n但同时又希望当两个元素可以判等的时候，让 Pair 也可以判等，这时就可以用扩展来实现这个功能。\\n\\n如下面的代码所示，使用扩展语法，约束了 T1 和 T2 在支持 equals 的情况下，Pair 也可以实现 equals 函数。\\n\\n```typescript\\nclass Pair<T1, T2> {\\n    var first: T1\\n    var second: T2\\n    public init(a: T1, b: T2) {\\n        first = a\\n        second = b\\n    }\\n}\\n\\ninterface Eq<T> {\\n    func equals(other: T): Bool\\n}\\n\\nextend<T1, T2> Pair<T1, T2> where T1 <: Eq<T1>, T2 <: Eq<T2> {\\n    public func equals(other: Pair<T1, T2>) {\\n        first.equals(other.first) && second.equals(other.second)\\n    }\\n}\\n\\nclass Foo <: Eq<Foo> {\\n    public func equals(other: Foo): Bool {\\n        true\\n    }\\n}\\n\\nmain() {\\n    let a = Pair(Foo(), Foo())\\n    let b = Pair(Foo(), Foo())\\n    println(a.equals(b)) // true\\n}\\n```\\n\\n## 接口扩展\\n\\n拓展泛型的同时一并实现泛型，称为接口拓展。\\n\\n```typescript\\ninterface PrintSizeable {\\n    func printSize(): Unit\\n}\\n\\nextend<T> Array<T> <: PrintSizeable {\\n    public func printSize() {\\n        println(\\"The size is ${this.size}\\")\\n    }\\n}\\n```\\n\\n当使用扩展为 `Array` 实现 `PrintSizeable` 之后，就相当于在 `Array` 定义时实现接口 `PrintSizeable`。\\n\\n因此可以将 `Array` 作为 `PrintSizeable` 的实现类型来使用了，如以下代码所示。\\n\\n```typescript\\nmain() {\\n    let a: PrintSizeable = Array<Int64>()\\n    a.printSize() // 0\\n}\\n```\\n\\n可以在同一个扩展内同时实现多个接口，多个接口之间使用 `&` 分开，接口的顺序没有先后关系。\\n\\n如下面代码所示，可以在扩展中为 `Foo` 同时实现 `I1`、`I2`、`I3`。\\n\\n```typescript\\ninterface I1 {\\n    func f1(): Unit\\n}\\n\\ninterface I2 {\\n    func f2(): Unit\\n}\\n\\ninterface I3 {\\n    func f3(): Unit\\n}\\n\\nclass Foo {}\\n\\nextend Foo <: I1 & I2 & I3 {\\n    public func f1(): Unit {}\\n    public func f2(): Unit {}\\n    public func f3(): Unit {}\\n}\\n```\\n\\n也可以在接口扩展中声明额外的泛型约束，来实现一些特定约束下才能满足的接口。\\n\\n例如可以让上面的 `Pair` 类型实现 `Eq` 接口，这样 `Pair` 自己也能成为一个符合 `Eq` 约束的类型，如下代码所示。\\n\\n```typescript\\nclass Pair<T1, T2> {\\n    var first: T1\\n    var second: T2\\n    public init(a: T1, b: T2) {\\n        first = a\\n        second = b\\n    }\\n}\\n\\ninterface Eq<T> {\\n    func equals(other: T): Bool\\n}\\n\\nextend<T1, T2> Pair<T1, T2> <: Eq<Pair<T1, T2>> where T1 <: Eq<T1>, T2 <: Eq<T2> {\\n    public func equals(other: Pair<T1, T2>) {\\n        first.equals(other.first) && second.equals(other.second)\\n    }\\n}\\n\\nclass Foo <: Eq<Foo> {\\n    public func equals(other: Foo): Bool {\\n        true\\n    }\\n}\\n\\nmain() {\\n    let a = Pair(Foo(), Foo())\\n    let b = Pair(Foo(), Foo())\\n    println(a.equals(b)) // true\\n}\\n```"}'),p={name:"仓颉入门到实战/49-拓展（1）/49-拓展（1）.md"};function h(k,s,t,e,r,E){return a(),n("div",null,[...s[0]||(s[0]=[l("",44)])])}const y=i(p,[["render",h]]);export{g as __pageData,y as default};
